// slice-header-check.mjs -- keep a published slice table's hand-written prose in step with its own generated histogram.
//
// The table's summary line is generated by slice-assemble.mjs, but the header and the provenance file are written by
// hand, and on 2026-11-07 three separate count sweeps in two days each left a stale number behind (A 328 vs 326,
// "107 条 weapon-wp" vs 118, "64 rows authored unknown" vs 47, "label unknown on 113 rows" vs 95). Chasing them one
// at a time is how a document ends up contradicting itself four lines above its own summary.
//
//   node MHGU/tools/mhgu/slice-header-check.mjs --table <slice.md> [--provenance <PROVENANCE.md>]
//
// It computes the histogram from the table's rows, then evaluates a small table of NAMED claims: an explicit regex
// and the value it must equal. A claim whose regex no longer matches the document is reported as MISSING (so a
// rewording cannot silently drop the check), and a claim whose number disagrees is a failure (exit 1).
import fs from "node:fs";

const arg = (k, d = null) => { const i = process.argv.indexOf(`--${k}`); return i >= 0 ? process.argv[i + 1] : d; };
const TABLE = arg("table");
const PROV = arg("provenance");
if (!TABLE) { console.error("usage: node MHGU/tools/mhgu/slice-header-check.mjs --table <slice.md> [--provenance <P.md>]"); process.exit(2); }

const text = fs.readFileSync(TABLE, "utf8");
const body = text.split(/\r?\n/);
const rows = [];
for (const l of body) {
  const m = /^\|\s*(0x[0-9a-f]+)\s*\|\s*([a-z-]+)\s*\|\s*([a-z]+)\s*\|\s*(A|B|C)\s*\|/.exec(l);
  if (m) rows.push({ addr: m[1], label: m[2], conf: m[4] });
}
const hist = {};
for (const r of rows) hist[r.label] = (hist[r.label] || 0) + 1;
const confs = { A: 0, B: 0, C: 0 };
for (const r of rows) confs[r.conf]++;
// Authored `conf unknown` rows are normalised to C on the way into the table; the header states how many were moved.
const authoredUnknown = (text.match(/\[revised|unknown/g) || []).length ? null : null;

const header = body.slice(0, body.findIndex((l) => /^\|\s*0x[0-9a-f]+/.test(l))).join("\n");
// Scope the provenance claims to the section about THIS table: the file also carries other tables' summaries, and
// an unscoped regex matched another table's "A 26 / B 29 / C 125" on the first run.
const provAll = PROV && fs.existsSync(PROV) ? fs.readFileSync(PROV, "utf8") : "";
const secStart = provAll.indexOf("### Result of the second route");
const secEnd = secStart >= 0 ? provAll.indexOf("\n## ", secStart) : -1;
const prov = secStart >= 0 ? provAll.slice(secStart, secEnd > secStart ? secEnd : undefined) : provAll;

// name | document | regex (first group is the number, or three groups for A/B/C triples) | expected
const CLAIMS = [
  ["header:weapon-wp count", header, /本批 (\d+) 条 `weapon-wp`/, hist["weapon-wp"]],
  ["prov:conf triple", prov, /A (\d+) \/ B (\d+) \/ C (\d+)/, [confs.A, confs.B, confs.C]],
  ["prov:rows labelled unknown", prov, /label\s*\n?`unknown` on (\d+) rows|`unknown` on (\d+) rows/, hist.unknown],
  ["prov:mentions 822 rows", prov, /822 rows/, 822, "flag"],
];
if (prov) {
  const m = /`conf A (\d+), B (\d+), C (\d+)`/.exec(prov);
  if (m) CLAIMS.push(["prov:conf A/B/C (inline)", prov, /`conf A (\d+), B (\d+), C (\d+)`/, [confs.A, confs.B, confs.C]]);
}

let fails = 0, checked = 0, missing = 0;
const tableRows = rows.length;
console.log(`table: ${TABLE}`);
console.log(`computed: ${tableRows} rows | A ${confs.A} B ${confs.B} C ${confs.C} | weapon-wp ${hist["weapon-wp"] ?? 0} | label unknown ${hist.unknown ?? 0}`);
for (const [name, doc, re, want] of CLAIMS) {
  const m = re.exec(doc);
  if (!m) { console.log(`  MISSING  ${name}  (regex ${re} matched nothing - reworded? update this check)`); missing++; continue; }
  // A claim with no capture group is a presence check ("the document mentions 822 rows"); everything else compares
  // the captured number(s) against the computed histogram.
  const presence = m.length === 1;
  const got = presence ? "present" : Array.isArray(want) ? m.slice(1, 4).map(Number) : Number(m[1]);
  const ok = presence ? true : Array.isArray(want) ? want.every((w, i) => w === got[i]) : want === got;
  checked++;
  if (ok) console.log(`  ok       ${name} = ${Array.isArray(got) ? got.join("/") : got}`);
  else { console.log(`  FAIL     ${name}: document says ${Array.isArray(got) ? got.join("/") : got}, computed ${Array.isArray(want) ? want.join("/") : want}`); fails++; }
}
console.log(`\n${fails} disagreement(s), ${missing} missing claim(s), ${checked} checked`);
if (fails) process.exit(1);
